// Reads and checks every setting before any HubSpot call. Both triggers land here.
// It never throws: problems are listed, and "Route Run" answers a Run Now call with a 500 that names them
// (a nightly run fails with the same list).
const text = v => String(v ?? '').trim();
const list = v => text(v).split(',').map(x => x.trim()).filter(Boolean);
const normKey = v => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const problems = [];

const whole = (name, value, fallback, lo, hi) => {
  if (text(value) === '') return fallback;
  const n = Number(text(value));
  if (!Number.isInteger(n) || n < lo || n > hi) {
    problems.push(`${name} must be a whole number from ${lo} to ${hi} (it is "${text(value)}")`);
    return fallback;
  }
  return n;
};
const decimal = (name, value, fallback, lo, hi) => {
  if (text(value) === '') return fallback;
  const n = Number(text(value));
  if (!Number.isFinite(n) || n < lo || n > hi) {
    problems.push(`${name} must be a number from ${lo} to ${hi} (it is "${text(value)}")`);
    return fallback;
  }
  return n;
};
const propertyName = (name, value, fallback) => {
  const v = text(value) === '' ? fallback : text(value);
  if (v && !/^[a-z0-9_]{1,100}$/.test(v)) {
    problems.push(`${name} "${v}" is not a HubSpot internal property name (lower case letters, digits and _)`);
    return '';
  }
  return v;
};
// A mapping table: {"raw value": "allowed value"}. Keys are compared after lower casing and turning anything that is
// not a letter or digit into a space, so "Google-Ads", "google ads" and " GOOGLE ADS " are the same key.
const mapTable = (name, raw, needed) => {
  if (!text(raw)) {
    if (needed) problems.push(`${name} is empty, but its property is set. Add the mapping table or clear the property setting`);
    return {};
  }
  let obj;
  try { obj = JSON.parse(raw); } catch (e) { obj = null; }
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) {
    problems.push(`${name} is not a JSON object like {"google ads": "Paid Search"}`);
    return {};
  }
  const out = {};
  for (const [k, v] of Object.entries(obj)) {
    if (typeof v !== 'string' || !v.trim() || !normKey(k)) {
      problems.push(`${name}: "${k}" needs a non empty text value`);
      continue;
    }
    out[normKey(k)] = v.trim();
  }
  return out;
};
const validTz = tz => { try { new Intl.DateTimeFormat('en-US', { timeZone: tz }); return true; } catch (e) { return false; } };
const httpUrl = v => /^https?:\/\/[^\s]+$/i.test(v);

const runNow = $('Run Now').isExecuted;
const body = runNow ? ($('Run Now').first().json.body || {}) : {};
const askedDry = body.dryRun === true || String(body.dryRun).toLowerCase() === 'true';
// DRY_RUN is on unless it is "false" (case and spaces ignored). The Run Now body can ask for a dry run, but never turn it off.
const dryRunSetting = text($env.DRY_RUN).toLowerCase() !== 'false';

const leadSourceProperty = propertyName('LEAD_SOURCE_PROPERTY', $env.LEAD_SOURCE_PROPERTY, 'lead_source');
const lifecycleTextProperty = propertyName('LIFECYCLE_TEXT_PROPERTY', $env.LIFECYCLE_TEXT_PROPERTY, '');
const freeDomains = text($env.FREE_EMAIL_DOMAINS)
  ? list($env.FREE_EMAIL_DOMAINS).map(d => d.toLowerCase())
  : ['gmail.com', 'googlemail.com', 'yahoo.com', 'ymail.com', 'outlook.com', 'hotmail.com', 'live.com', 'msn.com', 'icloud.com',
     'me.com', 'mac.com', 'aol.com', 'proton.me', 'protonmail.com', 'gmx.com', 'mail.com', 'zoho.com', 'yandex.com'];
const s = {
  trigger: runNow ? 'Run Now' : 'nightly run',
  dryRun: dryRunSetting || askedDry,
  dryRunSetting,
  hubspotApp: (text($env.HUBSPOT_APP_URL) || 'https://app.hubspot.com').replace(/\/+$/, ''),
  portalId: text($env.HUBSPOT_PORTAL_ID),
  pageSize: whole('HUBSPOT_PAGE_SIZE', $env.HUBSPOT_PAGE_SIZE, 100, 1, 100),
  maxPages: whole('MAX_CONTACT_PAGES', $env.MAX_CONTACT_PAGES, 200, 1, 1000),
  maxMerges: whole('MAX_MERGES_PER_RUN', $env.MAX_MERGES_PER_RUN, 10, 0, 50),
  maxAssignments: whole('MAX_ASSIGNMENTS_PER_RUN', $env.MAX_ASSIGNMENTS_PER_RUN, 100, 0, 1000),
  maxApprovals: whole('MAX_APPROVALS_PER_RUN', $env.MAX_APPROVALS_PER_RUN, 20, 1, 40),
  approvalHours: whole('APPROVAL_LINK_HOURS', $env.APPROVAL_LINK_HOURS, 72, 1, 336),
  backoffSeconds: decimal('BACKOFF_SECONDS', $env.BACKOFF_SECONDS, 2, 0.5, 30),
  countryCode: text($env.DEFAULT_COUNTRY_CODE) || '1',
  timezone: text($env.REPORT_TIMEZONE) || 'UTC',
  approvalUrl: text($env.APPROVAL_WEBHOOK_URL),
  dotPlusDomains: (text($env.EMAIL_DOT_PLUS_DOMAINS) ? list($env.EMAIL_DOT_PLUS_DOMAINS) : ['gmail.com', 'googlemail.com']).map(d => d.toLowerCase()),
  freeDomains,
  poolEntries: list($env.ROUND_ROBIN_OWNERS),
  awayEntries: list($env.AWAY_OWNERS).map(x => x.toLowerCase()),
  leadSourceProperty,
  lifecycleTextProperty,
  leadSourceMap: mapTable('LEAD_SOURCE_MAP', $env.LEAD_SOURCE_MAP, Boolean(leadSourceProperty)),
  lifecycleMap: mapTable('LIFECYCLE_MAP', $env.LIFECYCLE_MAP, Boolean(lifecycleTextProperty)),
};
if (!text($env.HUBSPOT_TOKEN)) problems.push('HUBSPOT_TOKEN is empty');
if (!httpUrl(text($env.SLACK_WEBHOOK_URL))) problems.push('SLACK_WEBHOOK_URL is empty or not a URL, so the report and the approval requests could not be sent');
if (text($env.APPROVAL_SECRET).length < 32) problems.push('APPROVAL_SECRET must be at least 32 characters, so approval links cannot be forged');
if (!httpUrl(s.approvalUrl)) problems.push('APPROVAL_WEBHOOK_URL must be the full https URL of the approval webhook');
if (!/^\d{1,3}$/.test(s.countryCode)) problems.push(`DEFAULT_COUNTRY_CODE must be 1 to 3 digits (it is "${s.countryCode}")`);
if (!validTz(s.timezone)) problems.push(`REPORT_TIMEZONE "${s.timezone}" is not a valid time zone`);
if (s.portalId && !/^\d+$/.test(s.portalId)) problems.push(`HUBSPOT_PORTAL_ID must be digits (it is "${s.portalId}")`);

// The properties every contact read asks for.
s.contactProperties = [...new Set(['email', 'firstname', 'lastname', 'phone', 'mobilephone', 'company', 'lifecyclestage',
  'hubspot_owner_id', 'createdate', 'hs_merged_object_ids', leadSourceProperty, lifecycleTextProperty].filter(Boolean))];
// Property definitions the field cleanup checks the mapping tables against.
s.propertyNames = [...new Set(['lifecyclestage', leadSourceProperty, lifecycleTextProperty].filter(Boolean))];
s.problems = problems;
s.route = problems.length ? (runNow ? 'refuse' : 'fail') : (runNow ? 'start' : 'scheduled');
s.startedAt = new Date().toISOString();
return [{ json: s }];

// Finds duplicates in the contacts just read, picks the record to keep, plans the merges (up to MAX_MERGES_PER_RUN)
// and the close matches that need a person, checks the owner list and the field mapping tables against HubSpot.
// Nothing is written here; the workflow's memory (approvals, rotation) is only read.
const s = $('Run Settings').first().json;
const problems = [], warnings = [];
const now = Date.now();

const normKey = v => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const display = p => [p.firstname, p.lastname].map(x => String(x || '').trim()).filter(Boolean).join(' ');

// ---------------------------------------------------------------- what HubSpot returned
const owners = $('HubSpot: Get Owners').all().flatMap(i => i.json.results || []);
const propResponse = $('HubSpot: Read Properties').first().json;
const propDefs = Object.fromEntries((propResponse.results || []).map(p => [p.name, p]));
const pages = $('HubSpot: List Contacts').all().map(i => i.json);
const seen = new Set();
const contacts = [];
for (const page of pages) {
  for (const r of page.results || []) {
    const id = String(r.id);
    if (!seen.has(id) && r.archived !== true) { seen.add(id); contacts.push(r); }
  }
}
const lastPage = pages[pages.length - 1] || {};
if (lastPage.paging && lastPage.paging.next && lastPage.paging.next.after) {
  warnings.push(`Only the first ${contacts.length} contacts were read (MAX_CONTACT_PAGES is ${s.maxPages}). Raise it to check the rest.`);
}

// ---------------------------------------------------------------- owners and the round robin pool
const activeOwners = owners.filter(o => o.archived !== true);
const ownerName = o => [o.firstName, o.lastName].filter(Boolean).join(' ') || o.email || `owner ${o.id}`;
const ownerNames = Object.fromEntries(owners.map(o => [String(o.id), ownerName(o)]));
const byId = new Map(activeOwners.map(o => [String(o.id), o]));
const byEmail = new Map(activeOwners.filter(o => o.email).map(o => [String(o.email).toLowerCase(), o]));
const away = new Set(s.awayEntries);
const pool = [];
for (const entry of s.poolEntries) {
  const o = byId.get(entry) || byEmail.get(entry.toLowerCase());
  if (!o) { problems.push(`ROUND_ROBIN_OWNERS: "${entry}" is not an active HubSpot owner, so it was left out of the rotation`); continue; }
  if (o.type && o.type !== 'PERSON') { problems.push(`ROUND_ROBIN_OWNERS: "${entry}" is a ${String(o.type).toLowerCase()}, not a person, so it was left out of the rotation`); continue; }
  const id = String(o.id);
  if (pool.some(p => p.id === id)) continue;
  pool.push({ id, name: ownerName(o), email: o.email || '', away: away.has(id) || away.has(String(o.email || '').toLowerCase()) });
}
for (const a of s.awayEntries) {
  if (!pool.some(p => p.id === a || p.email.toLowerCase() === a)) warnings.push(`AWAY_OWNERS: "${a}" is not in the rotation, so it changes nothing`);
}
const routingOn = s.poolEntries.length > 0 && s.maxAssignments > 0;
if (routingOn && !pool.some(p => !p.away)) problems.push('Nobody in ROUND_ROBIN_OWNERS is available (all are away or not valid owners), so unowned contacts stay unowned');

// ---------------------------------------------------------------- field rules, checked against the property definitions
const fieldRules = {};
const stage = propDefs.lifecyclestage;
if (!stage) problems.push('HubSpot did not return the lifecyclestage property definition');
const stageOptions = stage ? (stage.options || []).filter(o => o.hidden !== true) : [];
const stageOrder = Object.fromEntries(stageOptions.map((o, i) => [o.value, Number.isFinite(o.displayOrder) && o.displayOrder >= 0 ? o.displayOrder : 1000 + i]));
const stageLabels = Object.fromEntries(stageOptions.map(o => [o.value, o.label]));
if (s.lifecycleTextProperty) {
  const def = propDefs[s.lifecycleTextProperty];
  if (!def) {
    problems.push(`LIFECYCLE_TEXT_PROPERTY "${s.lifecycleTextProperty}" does not exist on contacts, so lifecycle stages were not cleaned`);
  } else if (stage) {
    const map = {};
    for (const [k, v] of Object.entries(s.lifecycleMap)) {
      if (stageOrder[v] === undefined) problems.push(`LIFECYCLE_MAP: "${v}" is not a lifecycle stage in this HubSpot account (use the internal value, for example marketingqualifiedlead), so "${k}" was ignored`);
      else map[k] = v;
    }
    const byKey = {};
    for (const o of stageOptions) { byKey[normKey(o.value)] = o.value; byKey[normKey(o.label)] = o.value; }
    fieldRules.lifecycle = { textProperty: s.lifecycleTextProperty, map, byKey, order: stageOrder, labels: stageLabels };
  }
}
if (s.leadSourceProperty) {
  const def = propDefs[s.leadSourceProperty];
  if (!def) {
    problems.push(`LEAD_SOURCE_PROPERTY "${s.leadSourceProperty}" does not exist on contacts, so lead sources were not cleaned`);
  } else if (def.modificationMetadata && def.modificationMetadata.readOnlyValue === true) {
    problems.push(`LEAD_SOURCE_PROPERTY "${s.leadSourceProperty}" is read only in HubSpot (HubSpot calculates it), so lead sources were not cleaned. Use your own text or dropdown property`);
  } else {
    const isEnum = def.type === 'enumeration';
    const options = isEnum ? (def.options || []).filter(o => o.hidden !== true).map(o => o.value) : [];
    const map = {};
    for (const [k, v] of Object.entries(s.leadSourceMap)) {
      if (isEnum && !options.includes(v)) problems.push(`LEAD_SOURCE_MAP: "${v}" is not an option of ${s.leadSourceProperty}, so "${k}" was ignored`);
      else map[k] = v;
    }
    const allowed = isEnum ? options : [...new Set(Object.values(map))];
    const byKey = {};
    for (const v of allowed) byKey[normKey(v)] = v;
    if (isEnum) for (const o of def.options || []) if (o.hidden !== true) byKey[normKey(o.label)] = o.value;
    fieldRules.leadSource = { property: s.leadSourceProperty, type: def.type, allowed, map, byKey };
  }
}

// ---------------------------------------------------------------- normalizing for matching
const dotPlus = new Set(s.dotPlusDomains);
const free = new Set(s.freeDomains);
function normEmail(raw) {
  const e = String(raw || '').trim().toLowerCase();
  const m = /^([^@\s]+)@([^@\s]+\.[^@\s]+)$/.exec(e);
  if (!m) return null;
  let [, local, domain] = m;
  if (domain === 'googlemail.com') domain = 'gmail.com';
  // Gmail ignores dots and anything after a + in the part before the @. Only for the domains listed in EMAIL_DOT_PLUS_DOMAINS.
  if (dotPlus.has(domain) || (domain === 'gmail.com' && dotPlus.has('googlemail.com'))) local = local.split('+')[0].replace(/\./g, '');
  return local ? `${local}@${domain}` : null;
}
function normPhone(raw) {
  let t = String(raw || '').trim();
  if (!t) return null;
  t = t.split(/\s*(?:ext\.?|extension|x|#)\s*\d+\s*$/i)[0];
  const plus = t.startsWith('+');
  let digits = t.replace(/\D/g, '');
  if (!plus) {
    if (digits.startsWith('00')) digits = digits.slice(2);
    else if (s.countryCode === '1' && digits.length === 11 && digits.startsWith('1')) { /* already has the country code */ }
    else if (s.countryCode === '1' && digits.length === 10) digits = '1' + digits;
    else if (s.countryCode !== '1') digits = s.countryCode + digits.replace(/^0/, '');
  }
  // Too short, or a placeholder such as 000-000-0000
  if (digits.length < 8 || digits.length > 15 || /^(\d)\1+$/.test(digits.slice(-7))) return null;
  return '+' + digits;
}
const normName = (first, last) => {
  const f = normKey(first), l = normKey(last);
  return f && l ? `${f} ${l}` : null;
};
// "Northwind Traders Inc." and "Northwind Traders" are one company, and so are "Smith & Sons" and "Smith and Sons".
const SUFFIX = /\b(and|inc|incorporated|llc|l l c|ltd|limited|co|corp|corporation|company|gmbh|plc|pty|sa|srl|bv)\b/g;
const normCompany = raw => {
  const k = normKey(String(raw || '').replace(/&/g, ' and ')).replace(SUFFIX, ' ').replace(/\s+/g, ' ').trim();
  return k || null;
};

const C = new Map();
for (const r of contacts) {
  const p = r.properties || {};
  const email = normEmail(p.email);
  const domain = email ? email.split('@')[1] : null;
  C.set(String(r.id), {
    id: String(r.id), p,
    created: Date.parse(p.createdate || r.createdAt || '') || 0,
    email, domain: domain && !free.has(domain) ? domain : null,
    phones: [...new Set([normPhone(p.phone), normPhone(p.mobilephone)].filter(Boolean))],
    name: normName(p.firstname, p.lastname),
    first: normKey(p.firstname), last: normKey(p.lastname),
    company: normCompany(p.company),
    history: String(p.hs_merged_object_ids || '').split(';').map(x => x.trim()).filter(Boolean),
    label: display(p) || String(p.email || '').trim() || `record ${r.id}`,
  });
}
// The record to keep: the one created first (it carries the original source and the longest history).
// Ties go to the lower record ID.
const older = (a, b) => (a.created - b.created) || (Number(a.id) - Number(b.id)) || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0);

// ---------------------------------------------------------------- exact matches (union find)
const parent = new Map([...C.keys()].map(id => [id, id]));
const emailsOf = new Map([...C.values()].map(c => [c.id, new Set(c.email ? [c.email] : [])]));
const reasonsOf = new Map([...C.keys()].map(id => [id, new Set()]));
const namesOf = new Map([...C.values()].map(c => [c.id, c.first || c.last ? [{ f: c.first, l: c.last }] : []]));
const find = id => { while (parent.get(id) !== id) { parent.set(id, parent.get(parent.get(id))); id = parent.get(id); } return id; };
const union = (a, b, reason) => {
  const ra = find(a), rb = find(b);
  if (ra === rb) { reasonsOf.get(ra).add(reason); return true; }
  parent.set(rb, ra);
  for (const e of emailsOf.get(rb)) emailsOf.get(ra).add(e);
  for (const n of namesOf.get(rb)) namesOf.get(ra).push(n);
  for (const r of reasonsOf.get(rb)) reasonsOf.get(ra).add(r);
  reasonsOf.get(ra).add(reason);
  return true;
};
const sorted = [...C.values()].sort(older);
const byEmailKey = new Map();
for (const c of sorted) if (c.email) { if (!byEmailKey.has(c.email)) byEmailKey.set(c.email, []); byEmailKey.get(c.email).push(c.id); }
for (const ids of byEmailKey.values()) for (const id of ids.slice(1)) union(ids[0], id, 'same email');
// A shared phone is only an exact match when the records do not hold two different emails AND their names agree: the
// same last name, and first names that match or where one starts the other ("Marc" and "Marcus", "O." and "Owen").
// An office line is shared by several people, and a record without an email says nothing about who it is, so
// anything else on one phone goes to a person instead of being merged.
const firstOk = (a, b) => !a || !b || a.startsWith(b) || b.startsWith(a);
const nameClash = (xs, ys) => {
  if (!xs.length || !ys.length) return 'same phone, no name to compare';
  for (const x of xs) for (const y of ys) {
    if (!x.l || !y.l) return 'same phone, a last name is missing';
    if (x.l !== y.l || !firstOk(x.f, y.f)) return 'same phone, different names';
  }
  return '';
};
const phoneConflicts = [];
const byPhoneKey = new Map();
for (const c of sorted) for (const ph of c.phones) { if (!byPhoneKey.has(ph)) byPhoneKey.set(ph, []); byPhoneKey.get(ph).push(c.id); }
for (const ids of byPhoneKey.values()) {
  for (const id of ids.slice(1)) {
    const ra = find(ids[0]), rb = find(id);
    if (ra === rb) { reasonsOf.get(ra).add('same phone'); continue; }
    const together = new Set([...emailsOf.get(ra), ...emailsOf.get(rb)]);
    const clash = together.size > 1 ? 'same phone, different emails' : nameClash(namesOf.get(ra), namesOf.get(rb));
    if (clash) phoneConflicts.push([ids[0], id, clash]);
    else union(ids[0], id, 'same phone');
  }
}
const components = new Map();
for (const id of C.keys()) { const r = find(id); if (!components.has(r)) components.set(r, []); components.get(r).push(C.get(id)); }
const entities = new Map();   // root -> entity
for (const [root, members] of components) {
  members.sort(older);
  entities.set(root, {
    root, members, keep: members[0],
    names: new Set(members.map(m => m.name).filter(Boolean)),
    companies: new Set(members.map(m => m.company).filter(Boolean)),
    domains: new Set(members.map(m => m.domain).filter(Boolean)),
    ids: [...new Set(members.flatMap(m => [m.id, ...m.history]))],
    reasons: [...reasonsOf.get(root)].sort(),
  });
}
const entityOf = id => entities.get(find(id));
const exactGroups = [...entities.values()].filter(e => e.members.length > 1).sort((a, b) => older(a.keep, b.keep));

// ---------------------------------------------------------------- the merge plan, capped
const allMerges = [];
for (const g of exactGroups) {
  for (const m of g.members.slice(1)) {
    allMerges.push({
      groupId: g.keep.id, primaryId: g.keep.id, secondaryId: m.id, reason: g.reasons.join(' and '),
      primaryName: g.keep.label, secondaryName: m.label,
    });
  }
}
const merges = allMerges.slice(0, s.maxMerges).map((m, i) => Object.assign(m, { seq: i + 1 }));
const deferredMerges = allMerges.length - merges.length;

// ---------------------------------------------------------------- close matches for a person
const pairs = new Map();
const addPair = (e1, e2, reason) => {
  if (!e1 || !e2 || e1 === e2) return;
  const [a, b] = older(e1.keep, e2.keep) <= 0 ? [e1, e2] : [e2, e1];
  const key = `${a.keep.id}|${b.keep.id}`;
  if (!pairs.has(key)) pairs.set(key, { a, b, reasons: new Set() });
  pairs.get(key).reasons.add(reason);
};
const byName = new Map();
for (const e of entities.values()) for (const n of e.names) { if (!byName.has(n)) byName.set(n, []); byName.get(n).push(e); }
for (const list of byName.values()) {
  for (let i = 0; i < list.length; i++) {
    for (let j = i + 1; j < list.length; j++) {
      const [e1, e2] = [list[i], list[j]];
      if ([...e1.companies].some(c => e2.companies.has(c))) addPair(e1, e2, 'same name and company');
      if ([...e1.domains].some(d => e2.domains.has(d))) addPair(e1, e2, 'same name and email domain');
    }
  }
}
for (const [x, y, why] of phoneConflicts) addPair(entityOf(x), entityOf(y), why);

const st = $getWorkflowStaticData('global');
const approvals = st.approvals || {};
const memoryFor = (a, b) => {
  // Records keep their old IDs in hs_merged_object_ids, so a decision survives a later merge of either record.
  let found = null;
  for (const x of a.ids) for (const y of b.ids) {
    const entry = approvals[[x, y].sort().join('|')];
    if (entry && (!found || entry.status === 'skipped')) found = entry;
  }
  return found;
};
const card = c => ({
  id: c.id, name: c.label, email: String(c.p.email || ''), phone: String(c.p.phone || c.p.mobilephone || ''),
  company: String(c.p.company || ''), created: c.p.createdate || '',
});
const newPairs = [], waitingPairs = [], skippedPairs = [], postponedPairs = [];
for (const pr of [...pairs.values()].sort((x, y) => older(x.a.keep, y.a.keep) || older(x.b.keep, y.b.keep))) {
  const reason = [...pr.reasons].sort().join('; ');
  const memo = memoryFor(pr.a, pr.b);
  const item = { pairKey: [pr.a.keep.id, pr.b.keep.id].sort().join('|'), primaryId: pr.a.keep.id, secondaryId: pr.b.keep.id, reason,
    primary: card(pr.a.keep), secondary: card(pr.b.keep) };
  if (memo && memo.status === 'skipped') { skippedPairs.push(item); continue; }
  if (memo && memo.status === 'waiting' && Date.parse(memo.expiresAt) > now) { waitingPairs.push(item); continue; }
  // A side that still has exact duplicates to merge gets a new record ID when they merge, so ask after that. With
  // automatic merging off (MAX_MERGES_PER_RUN is 0) that merge never comes, so ask now.
  if (s.maxMerges > 0 && (pr.a.members.length > 1 || pr.b.members.length > 1)) { postponedPairs.push(item); continue; }
  newPairs.push(item);
}
const askNow = newPairs.slice(0, s.maxApprovals);
const morePairs = newPairs.length - askNow.length;

// Sets of records that are (or may be) one person. Owners are assigned per set, so two reps never chase one person.
const dupSets = [
  ...exactGroups.map(g => g.members.map(m => m.id)),
  ...[...pairs.values()].filter(pr => !skippedPairs.some(sp => sp.pairKey === [pr.a.keep.id, pr.b.keep.id].sort().join('|')))
    .map(pr => [...pr.a.members, ...pr.b.members].map(m => m.id)),
