return [{ json: {
  dryRun: s.dryRun,
  counts: { contacts: contacts.length, exactGroups: exactGroups.length, exactRecords: allMerges.length, closePairs: pairs.size },
  merges, deferredMerges, allMergeCount: allMerges.length,
  exactGroups: exactGroups.map(g => ({ keepId: g.keep.id, keepName: g.keep.label, ids: g.members.map(m => m.id), reason: g.reasons.join(' and ') })),
  newPairs: askNow, morePairs, waitingCount: waitingPairs.length, skippedCount: skippedPairs.length, postponedCount: postponedPairs.length,
  dupSets, ownerPool: pool, ownerNames, routingOn, fieldRules, stageOrder,
