// Checks every planned merge against a fresh read, right before merging. A record that was merged or deleted in
// HubSpot since the contact list was read is skipped and reported, never merged blindly.
// HubSpot gives a merged record a new ID and keeps the old IDs in hs_merged_object_ids. Its docs do not say whether a
// read by an old ID returns the record it now belongs to or nothing, so both are handled: a record under another ID,
// or one that lists the old ID, was merged; no record at all means merged or deleted, and is never merged blindly.
const plan = $('Plan Cleanup').first().json;
const read = $input.first().json;
const results = read.results || [];
const history = r => String((r.properties || {}).hs_merged_object_ids || '').split(';').map(x => x.trim()).filter(Boolean);
