const merges = [], skipped = [];
const blockedGroups = new Map();
for (const m of plan.merges) {
  if (blockedGroups.has(m.groupId)) { skipped.push({ ...m, why: blockedGroups.get(m.groupId) }); continue; }
  const keep = resolve(m.primaryId), other = resolve(m.secondaryId);
  let why = '';
  if (keep && other && String(keep.id) === String(other.id)) why = 'already merged in HubSpot by someone else';
  else if (!keep || String(keep.id) !== m.primaryId) {
