    blockedGroups.set(m.groupId, why);
  } else if (!other) why = 'no longer in HubSpot under this ID (merged or deleted since the read)';
  else if (String(other.id) !== m.secondaryId) why = `already merged into record ${other.id} in HubSpot by someone else`;
  if (why) skipped.push({ ...m, why });
