}
if (!merges.length) return [{ json: { none: true, skipped } }];
return merges.map(m => ({ json: { ...m, skipped } }));

// One merge per pass. HubSpot gives the merged record a new ID, so the second merge of a group goes into the ID the
// first merge returned.
const m = $input.first().json;
const prev = $('Record Merge').isExecuted ? $('Record Merge').first().json : null;
const primaryNow = prev && prev.groupId === m.groupId && prev.survivorId ? prev.survivorId : m.primaryId;
return [{ json: {
  seq: m.seq, groupId: m.groupId, primaryId: m.primaryId, secondaryId: m.secondaryId, reason: m.reason,
  primaryName: m.primaryName, secondaryName: m.secondaryName, primaryNow,
  writeKey: `merge-${m.seq}`, attempt: 1,
  request: { primaryObjectId: primaryNow, objectIdToMerge: m.secondaryId },
} }];

// Reads HubSpot's answer to a write and decides: done, or wait and try again.
// Rate limits (429), a locked record (423), server errors (5xx) and lost connections are tried again up to 5 times,
// waiting BACKOFF_SECONDS, then twice as long each time (2, 4, 8, 16 seconds by default), or longer when HubSpot sends
// Retry-After. HubSpot's burst limit is counted per 10 seconds, so the waits add up to more than one window.
// A 429 for the DAILY limit is not tried again: it only resets at midnight.
const s = $('Run Settings').first().json;
const spec = $('Next Merge').first().json;
const waited = $('Wait: Merge Backoff').isExecuted ? $('Wait: Merge Backoff').first().json : null;
const attempt = waited && waited.writeKey === spec.writeKey ? waited.attempt : 1;
const statuses = (waited && waited.writeKey === spec.writeKey ? waited.statuses : null) || [];
const MAX_TRIES = 5;

const r = $input.first().json;
const status = Number(r.statusCode) || 0;   // 0: no answer (timeout or lost connection)
