  ...spec, retry: false, attempts: attempt, statuses: allStatuses, status, response: typeof body === 'object' ? body : null,
  message: daily ? `HubSpot's daily API limit is used up (429 DAILY), so it was not tried again: ${message}` : message,
} }];

// The outcome of one merge. Every merge ends here exactly once, so the report can list each one, including a group
// where the first merge worked and a later one did not.
const r = $input.first().json;
const ok = r.status >= 200 && r.status < 300 && r.response && r.response.id;
const gone = r.status === 404 || (r.response && r.response.category === 'OBJECT_NOT_FOUND');
let outcome = 'failed';
if (ok) outcome = 'merged';
else if (gone) outcome = 'already_merged';
return [{ json: {
  seq: r.seq, groupId: r.groupId, primaryId: r.primaryId, primaryNow: r.primaryNow, secondaryId: r.secondaryId,
  primaryName: r.primaryName, secondaryName: r.secondaryName, reason: r.reason,
  outcome,
  newId: ok ? String(r.response.id) : null,
  survivorId: ok ? String(r.response.id) : r.primaryNow,
  attempts: r.attempts, statuses: r.statuses, status: r.status,
  message: ok ? '' : (gone ? `HubSpot no longer has one of the records (${r.message})` : r.message),
} }];

// Plans the field fixes and the owner assignments on the contacts as they are after this run's merges.
// Live: merged records come from a fresh read (their new IDs), which also settles merges HubSpot answered with an error.
// Dry run: merges are predicted with HubSpot's documented
// merge rules (the kept record's values win, empty fields are filled from the other record, the furthest lifecycle
// stage is kept). Only properties whose value actually changes are sent, and contacts without a change are left out.
const s = $('Run Settings').first().json;
const plan = $('Plan Cleanup').first().json;
const rules = plan.fieldRules || {};
const stageOrder = plan.stageOrder || {};
const problems = [], warnings = [];
const normKey = v => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const filled = v => v !== undefined && v !== null && String(v).trim() !== '';
const label = c => [c.p.firstname, c.p.lastname].map(x => String(x || '').trim()).filter(Boolean).join(' ') || String(c.p.email || '').trim() || `record ${c.id}`;

// ---------------------------------------------------------------- the contacts as read
const cur = new Map();
for (const page of $('HubSpot: List Contacts').all()) {
  for (const r of page.json.results || []) {
    const id = String(r.id);
    if (!cur.has(id) && r.archived !== true) cur.set(id, { id, p: { ...(r.properties || {}) }, created: Date.parse((r.properties || {}).createdate || r.createdAt || '') || 0 });
  }
}

// ---------------------------------------------------------------- field cleanup rules
function cleanLeadSource(value) {
  const rule = rules.leadSource;
  const v = String(value);
  if (rule.allowed.includes(v)) return v;
  const k = normKey(v);
  return rule.map[k] || rule.byKey[k] || null;
}
