  const rule = rules.lifecycle;
  const k = normKey(raw);
  return rule.map[k] || rule.byKey[k] || null;
}
function fieldFixes(c) {
  const out = { props: {}, changes: [], unmapped: [], backward: [] };
  if (rules.leadSource) {
    const prop = rules.leadSource.property, v = c.p[prop];
    if (filled(v)) {
      const t = cleanLeadSource(v);
      if (t === null) out.unmapped.push({ field: 'lead source', value: String(v) });
      else if (t !== v) { out.props[prop] = t; out.changes.push({ field: 'lead source', from: String(v), to: t }); }
    }
  }
  if (rules.lifecycle) {
    const raw = c.p[rules.lifecycle.textProperty];
    if (filled(raw)) {
      const t = cleanStage(raw);
      const now = String(c.p.lifecyclestage || '');
      if (t === null) out.unmapped.push({ field: 'lifecycle stage', value: String(raw) });
      else if (now === t) { /* already right */ }
      // HubSpot only moves lifecycle stage forward through the API. A stage further along is never moved back.
      else if (now && (rules.lifecycle.order[now] ?? -1) > (rules.lifecycle.order[t] ?? -1)) out.backward.push({ from: now, to: t, raw: String(raw) });
      else { out.props.lifecyclestage = t; out.changes.push({ field: 'lifecycle stage', from: now || '(empty)', to: t, raw: String(raw) }); }
