}
const messyCount = list => list.reduce((n, c) => { const f = fieldFixes(c); return n + f.changes.length + f.unmapped.length; }, 0);
const before = {
  contacts: cur.size,
  unowned: [...cur.values()].filter(c => !filled(c.p.hubspot_owner_id)).length,
  messy: messyCount([...cur.values()]),
};

// ---------------------------------------------------------------- apply this run's merges to the picture
function predictMerge(keep, other, newId) {
  const p = { ...keep.p };
  for (const [k, v] of Object.entries(other.p)) if (!filled(p[k]) && filled(v)) p[k] = v;
  const a = keep.p.lifecyclestage, b = other.p.lifecyclestage;
  if (filled(a) && filled(b)) p.lifecyclestage = (stageOrder[b] ?? -1) > (stageOrder[a] ?? -1) ? b : a;
