const uncertain = new Set();   // records whose state is not known after this run: left for the next run
const rename = {};
const survivors = new Set();
const resolveId = id => { let x = id, n = 0; while (rename[x] && n++ < 100) x = rename[x]; return x; };
const applyMerge = (keepId, otherId, newId) => {
