  const keep = cur.get(k), other = k === o ? null : cur.get(o);
  if (keep && other) { cur.delete(k); cur.delete(o); cur.set(newId, predictMerge(keep, other, newId)); }
  else if (keep && k !== newId) { cur.delete(k); cur.set(newId, { ...keep, id: newId }); }
  for (const x of new Set([keepId, otherId, k, o])) if (x !== newId) rename[x] = newId;
