  // settles it: when both IDs now lead to one record, the records are one and the merge counts as done.
  const hist = r => String((r.properties || {}).hs_merged_object_ids || '').split(';').map(x => x.trim()).filter(Boolean);
  const found = id => (fresh || []).find(r => String(r.id) === id) || (fresh || []).find(r => hist(r).includes(id)) || null;
  for (const m of mergeResults) {
    if (m.outcome !== 'failed' || !fresh) continue;
    const a = found(String(m.primaryNow)), b = found(String(m.secondaryId));
    if (a && b && String(a.id) === String(b.id)) Object.assign(m, { outcome: 'merged', newId: String(a.id), survivorId: String(a.id), confirmedByRead: true });
  }
  for (const m of mergeResults) {
