// ---------------------------------------------------------------- field fixes
const updates = new Map();
const fixes = [], unmapped = {}, backward = [];
const want = (id, props) => { if (!updates.has(id)) updates.set(id, {}); Object.assign(updates.get(id), props); };
for (const c of cur.values()) {
  if (uncertain.has(c.id)) continue;
  const f = fieldFixes(c);
  if (f.changes.length) { fixes.push({ id: c.id, name: label(c), changes: f.changes }); want(c.id, f.props); }
  for (const u of f.unmapped) { const k = `${u.field}\u0000${u.value}`; unmapped[k] = (unmapped[k] || 0) + 1; }
  for (const b of f.backward) backward.push({ id: c.id, name: label(c), ...b });
}

// ---------------------------------------------------------------- owners, round robin
const owned = c => filled(c.p.hubspot_owner_id);
// Records that are (or may be) one person form one set: one owner for the whole set, and none at all when one of them
// already has an owner (the merge keeps that owner).
const setParent = new Map();
const sFind = x => { while (setParent.get(x) !== x) x = setParent.get(x); return x; };
for (const set of plan.dupSets) {
  const ids = [...new Set(set.map(resolveId))].filter(id => cur.has(id) && !uncertain.has(id));
  if (ids.length < 2) continue;
  for (const id of ids) if (!setParent.has(id)) setParent.set(id, id);
  for (const id of ids.slice(1)) { const a = sFind(ids[0]), b = sFind(id); if (a !== b) setParent.set(b, a); }
}
const sets = new Map();
for (const id of setParent.keys()) { const r = sFind(id); if (!sets.has(r)) sets.set(r, []); sets.get(r).push(id); }
const unassigned = { ownedDuplicate: 0, cap: 0, routingOff: 0, nobodyAvailable: 0 };
const slots = [];
const inSet = new Set();
for (const ids of sets.values()) {
  ids.forEach(id => inSet.add(id));
  const members = ids.map(id => cur.get(id));
  const free = members.filter(c => !owned(c));
  if (!free.length) continue;
  if (members.some(owned)) { unassigned.ownedDuplicate += free.length; continue; }
  slots.push({ ids: free.map(c => c.id).sort((a, b) => Number(a) - Number(b)), created: Math.min(...free.map(c => c.created)) });
}
for (const c of cur.values()) {
  if (uncertain.has(c.id) || inSet.has(c.id) || owned(c)) continue;
  slots.push({ ids: [c.id], created: c.created });
}
// Oldest first, so a backlog is worked through in order across runs.
slots.sort((a, b) => (a.created - b.created) || (Number(a.ids[0]) - Number(b.ids[0])));
const pool = plan.ownerPool || [];
const assignments = [];
const waitingCount = slots.reduce((n, sl) => n + sl.ids.length, 0);
if (!plan.routingOn) unassigned.routingOff = waitingCount;
else if (!pool.some(o => !o.away)) unassigned.nobodyAvailable = waitingCount;
else {
  // The rotation remembers the last owner who got a contact, by ID, so adding or removing people keeps the order fair.
  let idx = pool.findIndex(o => o.id === plan.lastOwnerId);
  let used = 0;
  for (let n = 0; n < slots.length; n++) {
    const slot = slots[n];
    if (used + slot.ids.length > s.maxAssignments) { unassigned.cap = slots.slice(n).reduce((t, sl) => t + sl.ids.length, 0); break; }
    do { idx = (idx + 1) % pool.length; } while (pool[idx].away);
    assignments.push({ ids: slot.ids, names: slot.ids.map(id => label(cur.get(id))), ownerId: pool[idx].id, ownerName: pool[idx].name });
    for (const id of slot.ids) want(id, { hubspot_owner_id: pool[idx].id });
