// ---------------------------------------------------------------- after, if every write works
const assignedIds = new Set(assignments.flatMap(a => a.ids));
const remaining = [...cur.values()];
const after = {
  contacts: remaining.length,
  unowned: remaining.filter(c => !owned(c) && !assignedIds.has(c.id)).length,
  messy: Object.values(unmapped).reduce((a, b) => a + b, 0)
    + remaining.filter(c => uncertain.has(c.id)).reduce((n, c) => { const f = fieldFixes(c); return n + f.changes.length + f.unmapped.length; }, 0),
};
const meta = {
  before, after, fixes, assignments, unassigned, backward,
  unmapped: Object.entries(unmapped).map(([k, n]) => ({ field: k.split('\u0000')[0], value: k.split('\u0000')[1], count: n })).sort((a, b) => b.count - a.count),
  uncertain: [...uncertain], problems, warnings,
  merges: mergeResults,
};

const inputs = [...updates.entries()].sort((a, b) => Number(a[0]) - Number(b[0]))
  .map(([id, properties]) => ({ id, properties, objectWriteTraceId: `contact-${id}` }));
if (!live || !inputs.length) return [{ json: { none: true, meta } }];
const out = [];
for (let i = 0; i < inputs.length; i += 100) {
  const batchNo = out.length + 1;
  out.push({ json: { batchNo, writeKey: `update-${batchNo}`, attempt: 1, request: { inputs: inputs.slice(i, i + 100) }, ...(batchNo === 1 ? { meta } : {}) } });
}
return out;

// Reads HubSpot's answer to a write and decides: done, or wait and try again.
// Rate limits (429), a locked record (423), server errors (5xx) and lost connections are tried again up to 5 times,
// waiting BACKOFF_SECONDS, then twice as long each time (2, 4, 8, 16 seconds by default), or longer when HubSpot sends
// Retry-After. HubSpot's burst limit is counted per 10 seconds, so the waits add up to more than one window.
// A 429 for the DAILY limit is not tried again: it only resets at midnight.
const s = $('Run Settings').first().json;
const spec = $('Loop: Updates').first().json;
const waited = $('Wait: Update Backoff').isExecuted ? $('Wait: Update Backoff').first().json : null;
const attempt = waited && waited.writeKey === spec.writeKey ? waited.attempt : 1;
const statuses = (waited && waited.writeKey === spec.writeKey ? waited.statuses : null) || [];
const MAX_TRIES = 5;

const r = $input.first().json;
const status = Number(r.statusCode) || 0;   // 0: no answer (timeout or lost connection)
let body = r.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* keep the text */ } }
const headers = r.headers || {};
const message = status === 0
