// Counts what was really saved and moves the rotation forward to the last owner who actually got a contact.
// A dry run saves nothing, not even the rotation.
const s = $('Run Settings').first().json;
const meta = $('Plan Updates').first().json.meta;
const results = $('Loop: Updates').isExecuted ? $('Loop: Updates').all(0).map(i => i.json) : [];
