const saved = id => !live || okIds.has(id);

const fixesDone = meta.fixes.filter(f => saved(f.id));
const assignmentsDone = meta.assignments.map(a => ({ ...a, ids: a.ids.filter(saved), names: a.names.filter((n, i) => saved(a.ids[i])) })).filter(a => a.ids.length);
const problems = [];
if (failed.length) {
  const names = Object.fromEntries([...meta.fixes.map(f => [f.id, f.name]), ...meta.assignments.flatMap(a => a.ids.map((id, i) => [id, a.names[i]]))]);
  const byMessage = {};
  for (const f of failed) (byMessage[f.message] = byMessage[f.message] || []).push(`${names[f.id] || 'record'} (${f.id})`);
  for (const [message, who] of Object.entries(byMessage)) problems.push(`HubSpot did not save the update for ${who.length} contact(s): ${who.slice(0, 10).join(', ')}${who.length > 10 ? ' and more' : ''}: ${message}`);
}
if (live && assignmentsDone.length) {
  const st = $getWorkflowStaticData('global');
  st.rotation = { lastOwnerId: assignmentsDone[assignmentsDone.length - 1].ownerId, updatedAt: new Date().toISOString() };
}
const failedIds = new Set(failed.map(f => f.id));
const after = { ...meta.after };
after.unowned += meta.assignments.reduce((n, a) => n + a.ids.filter(id => failedIds.has(id)).length, 0);
after.messy += meta.fixes.filter(f => failedIds.has(f.id)).reduce((n, f) => n + f.changes.length, 0);
return [{ json: { fixesDone, assignmentsDone, failedCount: failed.length, problems, after } }];

// One Approve and one Skip link per close match. Each link carries a small signed token: the pair, the action, a
// one-time nonce and the expiry time. The next node signs it with APPROVAL_SECRET (HMAC SHA-256), so a link cannot be
// changed or made up. The nonce is saved with the pair only after Slack accepted the message.
const s = $('Run Settings').first().json;
const plan = $('Plan Cleanup').first().json;
const expires = Math.floor(Date.now() / 1000) + s.approvalHours * 3600;
const out = [];
for (const pr of plan.newPairs) {
  const nonce = Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
  for (const action of ['approve', 'skip']) {
    const payload = { v: 1, a: action, k: pr.pairKey, p: pr.primaryId, s: pr.secondaryId, n: nonce, e: expires };
    out.push({ json: { pairKey: pr.pairKey, action, nonce, expires, payloadPart: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64url') } });
  }
}
return out;

// One Slack message for all new close matches, each with its Approve and Skip link. Contact data is escaped for
// Slack (&, <, >), so a name like "<!channel>" shows as text and pings nobody.
const s = $('Run Settings').first().json;
const plan = $('Plan Cleanup').first().json;
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const plain = t => t.replace(/[\u202f\u00a0]/g, ' ');
const day = iso => { const d = new Date(iso); return isNaN(d) ? '' : plain(new Intl.DateTimeFormat('en-US', { timeZone: s.timezone, month: 'short', day: 'numeric', year: 'numeric' }).format(d)); };
const when = unix => plain(new Intl.DateTimeFormat('en-US', { timeZone: s.timezone, month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(unix * 1000))) + ` (${s.timezone})`;
// Contact values are cut to 150 characters, so one section stays within Slack's 3,000 character limit even when a
// field holds a pasted note. The confirm page shows the full values.
const cut = t => { const v = String(t ?? ''); return v.length > 150 ? v.slice(0, 150).trimEnd() + '...' : v; };
const record = id => (s.portalId ? `<${s.hubspotApp}/contacts/${s.portalId}/record/0-1/${id}|record ${id}>` : `record ${id}`);
const describe = c => [esc(cut(c.name)), c.email && esc(cut(c.email)), c.phone && esc(cut(c.phone)), c.company && esc(cut(c.company)), c.created && `created ${day(c.created)}`]
  .filter(Boolean).join(', ') + ` (${record(c.id)})`;

const links = {};
for (const it of $input.all().map(i => i.json)) {
  const l = (links[it.pairKey] = links[it.pairKey] || {});
  l[it.action] = `${s.approvalUrl}${s.approvalUrl.includes('?') ? '&' : '?'}token=${it.payloadPart}.${it.sig}`;
  l.nonce = it.nonce;
  l.expires = it.expires;
}
const pairs = plan.newPairs.filter(pr => links[pr.pairKey] && links[pr.pairKey].approve && links[pr.pairKey].skip);
const n = pairs.length;
const expires = n ? links[pairs[0].pairKey].expires : 0;
const blocks = [{ type: 'section', text: { type: 'mrkdwn', text:
  `*HubSpot: ${n} possible duplicate${n === 1 ? '' : 's'} need${n === 1 ? 's' : ''} a decision*\n`
  + `The links work until ${when(expires)}. Opening a link shows a confirm page, and nothing changes in HubSpot until you press the button there. HubSpot cannot undo a merge.` } }];
pairs.forEach((pr, i) => {
  const l = links[pr.pairKey];
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text:
    `*${i + 1}. ${esc(cut(pr.primary.name))}*: ${esc(pr.reason)}\n`
    + `Keep: ${describe(pr.primary)}\n`
    + `Merge in: ${describe(pr.secondary)}\n`
    + `<${l.approve}|Approve merge>  |  <${l.skip}|Skip>` } });
});
const postedAt = new Date().toISOString();
const entries = {};
for (const pr of pairs) {
  const l = links[pr.pairKey];
  entries[pr.pairKey] = {
    status: 'waiting', nonce: l.nonce, expiresAt: new Date(l.expires * 1000).toISOString(), postedAt,
    primaryId: pr.primaryId, secondaryId: pr.secondaryId, reason: pr.reason, primary: pr.primary, secondary: pr.secondary,
  };
}
return [{ json: {
  text: `HubSpot: ${n} possible duplicate${n === 1 ? '' : 's'} need${n === 1 ? 's' : ''} a decision. Open this message in Slack to approve or skip each one.`,
  blocks, entries, count: n,
} }];

// Slack accepted the message, so the pairs now wait for a decision. Only now are their nonces saved: a link from a
// message that never arrived can never be used. Old decided entries are pruned after 60 days; skipped pairs are kept,
// so they are never suggested again.
const msg = $('Build Approval Message').first().json;
const st = $getWorkflowStaticData('global');
st.approvals = st.approvals || {};
for (const [key, entry] of Object.entries(msg.entries)) st.approvals[key] = entry;
const cutoff = Date.now() - 60 * 86400000;
for (const [key, e] of Object.entries(st.approvals)) {
  if (e.status === 'skipped') continue;
  const last = Date.parse(e.decidedAt || e.expiresAt || e.postedAt || '') || 0;
  if (last && last < cutoff) delete st.approvals[key];
}
return [{ json: { posted: Object.keys(msg.entries).length } }];

// Slack refused the approval message. Nothing is saved, so the same pairs are posted again by the next run.
const e = $input.first().json.error || {};
return [{ json: { message: `The approval request for ${$('Build Approval Message').first().json.count} close match(es) could not be posted to Slack (${e.message || e.description || 'unknown error'}), so nobody was asked. The next run posts them again.` } }];

// One Slack message per run: what was merged, what waits for a person, which fields were fixed, who got which
// contacts, the before and after counts and every problem. Contact data is escaped for Slack (&, <, >).
const s = $('Run Settings').first().json;
const plan = $('Plan Cleanup').first().json;
const fin = $('Finish Updates').first().json;
const meta = $('Plan Updates').first().json.meta;
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const live = !s.dryRun;
const prep = live && $('Prepare Merges').isExecuted ? $('Prepare Merges').first().json : null;
const skipped = [...((prep && prep.skipped) || [])];
// Each merge as settled by the read after the merges (a merge whose answer was lost counts as done there).
const merges = live ? (meta.merges || []) : [];
const posted = $('Save Approvals').isExecuted ? $('Build Approval Message').first().json.count : 0;
const approvalFailed = $('Approval Post Failed').isExecuted ? $('Approval Post Failed').first().json.message : '';
const problems = [...plan.problems, ...meta.problems, ...fin.problems];
const warnings = [...plan.warnings, ...meta.warnings];
const plural = (n, one, many) => `${n} ${n === 1 ? one : (many || one + 's')}`;
const top = (list, n = 15) => list.length > n ? [...list.slice(0, n), `and ${list.length - n} more`] : list;
const lines = [];

lines.push(live ? `*HubSpot cleanup* (${s.trigger})`
  : `*HubSpot cleanup* (${s.trigger}) *DRY RUN*: nothing was changed. This is what a real run would do.`);
const after = fin.after;
lines.push(`Before and after${live ? '' : ' (if run for real)'}: ${meta.before.contacts} to ${after.contacts} contacts, `
  + `${meta.before.unowned} to ${after.unowned} without an owner, ${meta.before.messy} to ${after.messy} messy field values`);

// ---------------------------------------------------------------- merges
if (live) {
  const groups = new Map();
  for (const m of merges) { if (!groups.has(m.groupId)) groups.set(m.groupId, []); groups.get(m.groupId).push(m); }
  const done = [];
  for (const list of groups.values()) {
    const ok = list.filter(m => m.outcome === 'merged');
    const bad = list.filter(m => m.outcome === 'failed');
    const gone = list.filter(m => m.outcome === 'already_merged');
    if (ok.length) {
      done.push(`${esc(list[0].primaryName)}: kept ${list[0].primaryId}, merged in ${ok.map(m => m.secondaryId).join(', ')} (${esc(list[0].reason)}), now record ${ok[ok.length - 1].newId}`);
    }
    for (const m of bad) {
      problems.push(`Merge failed: ${m.secondaryName} (${m.secondaryId}) into ${m.primaryName} (${m.primaryNow})`
        + (ok.length ? `, after ${plural(ok.length, 'other merge')} of this group worked` : '') + `: ${m.message} (${plural(m.attempts, 'try', 'tries')})`);
    }
    for (const m of gone) skipped.push({ ...m, why: m.message });
  }
  const mergedCount = merges.filter(m => m.outcome === 'merged').length;
  lines.push(`Merged: ${plural(mergedCount, 'exact duplicate')}`);
  for (const d of top(done)) lines.push(`\u2022 ${d}`);
  const confirmed = merges.filter(m => m.confirmedByRead).length;
  if (confirmed) lines.push(`HubSpot answered ${plural(confirmed, 'merge')} with an error, but the records are now one when read again, so ${confirmed === 1 ? 'it counts' : 'they count'} as merged.`);
} else {
  lines.push(`Would merge: ${plural(plan.merges.length, 'exact duplicate')}`);
  const byGroup = new Map();
  for (const m of plan.merges) { if (!byGroup.has(m.groupId)) byGroup.set(m.groupId, []); byGroup.get(m.groupId).push(m); }
  for (const d of top([...byGroup.values()].map(list => `${esc(list[0].primaryName)}: keep ${list[0].primaryId}, merge in ${list.map(m => m.secondaryId).join(', ')} (${esc(list[0].reason)})`))) lines.push(`\u2022 ${d}`);
}
if (plan.deferredMerges) lines.push(s.maxMerges === 0
  ? `Automatic merging is off (MAX_MERGES_PER_RUN is 0), so ${plural(plan.deferredMerges, 'exact duplicate')} ${plan.deferredMerges === 1 ? 'was' : 'were'} not merged.`
  : `Not merged this run: ${plural(plan.deferredMerges, 'exact duplicate')} over the cap of ${s.maxMerges} (MAX_MERGES_PER_RUN). The next run continues.`);
for (const k of top(skipped)) lines.push(`Not merged: ${esc(k.secondaryName)} (${k.secondaryId}) and ${esc(k.primaryName)} (${k.primaryId}): ${esc(k.why)}`);

// ---------------------------------------------------------------- approvals
const waitingBefore = plan.waitingCount;
if (live) {
  lines.push(`Waiting for approval: ${plural(posted + waitingBefore, 'close match', 'close matches')} (${posted} sent now, ${waitingBefore} from earlier runs)`);
} else {
  lines.push(`Would ask for approval: ${plural(plan.newPairs.length, 'close match', 'close matches')}${waitingBefore ? `, plus ${waitingBefore} already waiting` : ''}`);
}
if (plan.morePairs) lines.push(`${plural(plan.morePairs, 'more close match', 'more close matches')} will be sent in a later run (MAX_APPROVALS_PER_RUN is ${s.maxApprovals}).`);
if (plan.postponedCount) lines.push(`${plural(plan.postponedCount, 'close match', 'close matches')} will be sent once their exact duplicates are merged.`);
if (approvalFailed) problems.push(approvalFailed);

// ---------------------------------------------------------------- fields
const fixed = live ? fin.fixesDone : meta.fixes;
const fieldCounts = {};
for (const f of fixed) for (const c of f.changes) fieldCounts[c.field] = (fieldCounts[c.field] || 0) + 1;
const fieldTotal = Object.values(fieldCounts).reduce((a, b) => a + b, 0);
lines.push(`${live ? 'Fields fixed' : 'Would fix'}: ${fieldTotal}${fieldTotal ? ' (' + Object.entries(fieldCounts).map(([k, v]) => `${k} ${v}`).join(', ') + ')' : ''}`);
if (meta.unmapped.length) {
  lines.push(`Values not in the mapping table (left as they are): ${top(meta.unmapped.map(u => `${u.field} "${esc(u.value)}" (${u.count})`), 10).join(', ')}`);
}
if (meta.backward.length) {
  lines.push(`Lifecycle stage kept for ${plural(meta.backward.length, 'contact')}: the text says an earlier stage, and HubSpot only moves lifecycle stage forward (${top(meta.backward.map(b => `${esc(b.name)}: ${esc(b.from)}`), 5).join(', ')})`);
}

// ---------------------------------------------------------------- owners
const assigned = live ? fin.assignmentsDone : meta.assignments;
const perOwner = {};
for (const a of assigned) perOwner[a.ownerName] = (perOwner[a.ownerName] || 0) + a.ids.length;
const assignedTotal = Object.values(perOwner).reduce((a, b) => a + b, 0);
const awayNames = (plan.ownerPool || []).filter(o => o.away).map(o => esc(o.name));
lines.push(`${live ? 'Owners assigned' : 'Would assign owners'}: ${assignedTotal}${assignedTotal ? ' (' + Object.entries(perOwner).map(([k, v]) => `${esc(k)} ${v}`).join(', ') + ')' : ''}`
  + (awayNames.length ? `. Away: ${awayNames.join(', ')}` : ''));
const u = meta.unassigned;
if (u.ownedDuplicate) lines.push(`Left unowned: ${plural(u.ownedDuplicate, 'contact')} that ${u.ownedDuplicate === 1 ? 'duplicates' : 'duplicate'} a record with an owner (the merge keeps that owner).`);
if (u.cap) lines.push(`Left for the next run: ${plural(u.cap, 'unowned contact')} over the cap of ${s.maxAssignments} (MAX_ASSIGNMENTS_PER_RUN).`);
if (u.routingOff) lines.push(`Routing is off (ROUND_ROBIN_OWNERS is empty or MAX_ASSIGNMENTS_PER_RUN is 0): ${plural(u.routingOff, 'contact')} without an owner.`);
if (u.nobodyAvailable) lines.push(`Nobody was available to take ${plural(u.nobodyAvailable, 'unowned contact')}.`);

for (const w of warnings) lines.push(`Note: ${esc(w)}`);
// Problems are escaped once here: they reach Slack twice, in this summary and in the error alert of the failed run.
const safeProblems = problems.map(esc);
lines.push(safeProblems.length ? `*Problems: ${safeProblems.length}*` : 'Problems: none');
for (const p of safeProblems) lines.push(`\u2022 ${p}`);

return [{ json: { text: lines.join('\n'), problems: safeProblems } }];

// The report is the point of the run, so a summary Slack refused is a problem too: the run fails and n8n keeps it.
const e = $input.first().json.error || {};
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const problems = [...$('Build Summary').first().json.problems,
  esc(`The Slack summary could not be posted (${e.message || e.description || 'unknown error'}). Check SLACK_WEBHOOK_URL. The full summary is in this run's Build Summary node.`)];
return [{ json: { problems } }];

// Reads the token from an approval link (GET, from Slack) or from the confirm page's button (POST).
// Only a POST can change anything; a GET only shows the confirm page, so link previews and scanners are harmless.
const isPost = $('Approval Confirm').isExecuted;
const req = (isPost ? $('Approval Confirm') : $('Approval Link')).first().json;
const raw = String((isPost ? (req.body || {}).token : (req.query || {}).token) || '').trim();
const m = /^([A-Za-z0-9_-]{16,4000})\.([0-9a-f]{64})$/.exec(raw);
let payload = null;
if (m) {
  try { payload = JSON.parse(Buffer.from(m[1], 'base64url').toString('utf8')); } catch (e) { payload = null; }
}
const valid = Boolean(payload && payload.v === 1 && ['approve', 'skip'].includes(payload.a) && typeof payload.k === 'string'
  && /^\d+$/.test(String(payload.p)) && /^\d+$/.test(String(payload.s)) && typeof payload.n === 'string' && Number.isFinite(payload.e));
return [{ json: { isPost, token: m ? raw : '', payloadPart: m ? m[1] : '', givenSig: m ? m[2] : '', payload: valid ? payload : null } }];

// Decides what an approval link may do. In this order:
//   1. the signature must match (HMAC SHA-256 with APPROVAL_SECRET, compared in constant time), else 403 and an alert
//   2. the link must not have expired (the expiry is inside the signed token), else 410
//   3. the pair must still wait for a decision with this exact nonce, else 409 (used, or replaced by a newer link)
//   4. DRY_RUN must be off, else nothing happens
// A GET then only shows the confirm page. Only the POST from that page's button approves or skips.
const html = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const slack = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const page = (title, inner) => '<!doctype html><html lang="en"><head><meta charset="utf-8">'
  + '<meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex">'
  + `<title>${html(title)}</title><style>`
  + 'body{font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;max-width:560px;margin:40px auto;padding:0 16px;color:#1f2933;background:#fff;line-height:1.5}'
  + 'h1{font-size:22px}.card{border:1px solid #d9e2ec;border-radius:8px;padding:12px 16px;margin:8px 0 16px}.muted{color:#52606d;font-size:14px}'
  + 'button{font-size:16px;padding:10px 18px;border-radius:6px;border:0;background:#1f6feb;color:#fff;cursor:pointer}button.skip{background:#52606d}'
  + `</style></head><body><h1>${html(title)}</h1>${inner}</body></html>`;
const tz = (() => { const z = String($env.REPORT_TIMEZONE || '').trim() || 'UTC'; try { new Intl.DateTimeFormat('en-US', { timeZone: z }); return z; } catch (e) { return 'UTC'; } })();
const plainSpaces = t => t.replace(/[\u202f\u00a0]/g, ' ');
const when = value => {
  const d = typeof value === 'number' ? new Date(value * 1000) : new Date(value);
  if (isNaN(d)) return '';
  return plainSpaces(new Intl.DateTimeFormat('en-US', { timeZone: tz, month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' }).format(d)) + ` (${tz})`;
};
const t = $input.first().json;
const p = t.payload;
const secret = String($env.APPROVAL_SECRET || '');
const sameSig = (a, b) => {
  if (typeof a !== 'string' || typeof b !== 'string' || !a.length || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
};
const out = (route, httpStatus, title, inner, extra = {}) => [{ json: { route, httpStatus, html: page(title, inner), isPost: t.isPost, payload: p, ...extra } }];

if (secret.length < 32 || !p || !sameSig(t.givenSig, String(t.expectedSig || '').toLowerCase())) {
  const reason = secret.length < 32 ? 'APPROVAL_SECRET is shorter than 32 characters, so every approval link is refused'
    : (p ? 'its signature does not match' : 'it is not a complete approval link');
  return out('refused', 403, 'This link is not valid', '<p>This approval link was changed or did not come from the cleanup workflow, so nothing was done.</p>', { reason });
}
if (Date.now() / 1000 > p.e) {
  return out('closed', 410, 'This link has expired', `<p>It expired on ${html(when(p.e))}. Nothing was done. If these records are still duplicates, the next nightly run sends a new link.</p>`);
}
const st = $getWorkflowStaticData('global');
const entry = (st.approvals || {})[p.k];
if (!entry || entry.nonce !== p.n || entry.primaryId !== String(p.p) || entry.secondaryId !== String(p.s)) {
  return out('closed', 409, 'This link is no longer active', '<p>A newer link was sent for these records, or they no longer wait for a decision. Nothing was done.</p>');
}
if (entry.status !== 'waiting') {
  const word = { merged: 'merged', already_merged: 'merged in HubSpot', deleted: 'removed from HubSpot', skipped: 'skipped' }[entry.status] || entry.status;
  return out('closed', 409, `Already ${word}`, `<p>These records were already ${html(word)} on ${html(when(entry.decidedAt))}. This link can only be used once, so nothing was done.</p>`);
}
if (String($env.DRY_RUN || '').trim().toLowerCase() !== 'false') {
  return out('closed', 409, 'Dry run is on', '<p>DRY_RUN is on, so approvals do not change HubSpot. Nothing was done. The link still works once DRY_RUN is set to false.</p>');
}
if (!t.isPost) {
  const approve = p.a === 'approve';
  const card = c => `<div class="card"><strong>${html(c.name)}</strong><br>${[c.email, c.phone, c.company].filter(Boolean).map(html).join('<br>')}`
    + `<div class="muted">Record ${html(c.id)}${c.created ? `, created ${html(when(c.created).replace(/, \d+:\d+.*$/, ''))}` : ''}</div></div>`;
  const inner = `<p class="muted">Why they look like one person: ${html(entry.reason)}</p>`
    + `<p>${approve ? 'Keep' : 'Record 1'}:</p>${card(entry.primary)}<p>${approve ? 'Merge into it' : 'Record 2'}:</p>${card(entry.secondary)}`
    + (approve
      ? '<p>HubSpot keeps the first record\'s values, fills its empty fields from the second, adds the second email as an additional email and gives the merged record a new ID. A merge cannot be undone.</p>'
      : '<p>Skipping means these two records will not be suggested as duplicates again. Nothing changes in HubSpot.</p>')
    + `<form method="post" action="${html(String($env.APPROVAL_WEBHOOK_URL || ''))}"><input type="hidden" name="token" value="${html(t.token)}">`
    + `<button type="submit"${approve ? '' : ' class="skip"'}>${approve ? 'Merge these records' : 'Skip this pair'}</button></form>`
    + `<p class="muted">This link works until ${html(when(p.e))}.</p>`;
  return out('confirm', 200, approve ? 'Merge these two contacts?' : 'Skip this pair?', inner);
}
return out(p.a, 200, '', '', { entry });

// Skip: the pair is remembered as "not the same person" and never suggested again. HubSpot is not touched.
const html = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const slack = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const page = (title, inner) => '<!doctype html><html lang="en"><head><meta charset="utf-8">'
  + '<meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex">'
  + `<title>${html(title)}</title><style>`
  + 'body{font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;max-width:560px;margin:40px auto;padding:0 16px;color:#1f2933;background:#fff;line-height:1.5}'
  + 'h1{font-size:22px}.card{border:1px solid #d9e2ec;border-radius:8px;padding:12px 16px;margin:8px 0 16px}.muted{color:#52606d;font-size:14px}'
  + 'button{font-size:16px;padding:10px 18px;border-radius:6px;border:0;background:#1f6feb;color:#fff;cursor:pointer}button.skip{background:#52606d}'
  + `</style></head><body><h1>${html(title)}</h1>${inner}</body></html>`;
const tz = (() => { const z = String($env.REPORT_TIMEZONE || '').trim() || 'UTC'; try { new Intl.DateTimeFormat('en-US', { timeZone: z }); return z; } catch (e) { return 'UTC'; } })();
const plainSpaces = t => t.replace(/[\u202f\u00a0]/g, ' ');
const when = value => {
  const d = typeof value === 'number' ? new Date(value * 1000) : new Date(value);
  if (isNaN(d)) return '';
  return plainSpaces(new Intl.DateTimeFormat('en-US', { timeZone: tz, month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' }).format(d)) + ` (${tz})`;
};
const c = $input.first().json;
const st = $getWorkflowStaticData('global');
const entry = st.approvals[c.payload.k];
entry.status = 'skipped';
entry.decidedAt = new Date().toISOString();
const a = entry.primary, b = entry.secondary;
// A decided pair keeps only record IDs in n8n's memory: names and emails are not needed any more.
entry.primary = { id: entry.primaryId };
entry.secondary = { id: entry.secondaryId };
return [{ json: {
  httpStatus: 200,
  html: page('Skipped', `<p>${html(a.name)} (record ${html(entry.primaryId)}) and ${html(b.name)} (record ${html(entry.secondaryId)}) will not be suggested as duplicates again. Nothing was changed in HubSpot.</p>`),
  note: `*Duplicate skipped*: ${slack(a.name)} (record ${entry.primaryId}) and ${slack(b.name)} (record ${entry.secondaryId}) are kept apart and will not be suggested again.`,
} }];

// Reads both records again right before merging. If someone merged them in HubSpot in the meantime, or one of them
// was deleted, there is nothing to merge. If HubSpot answers the old ID of a record merged into a third one with the
// record it now belongs to (community answers say it does; the docs do not say), that record is merged, because the
// approval was about these people.
// The same read runs again after a merge call that failed: one record then means the merge went through (the answer
// was lost, or a second click merged them first); two records mean it did not.
const c = $('Check Approval').first().json;
const p = c.payload;
const mergeError = $('Merge Pair Error').isExecuted ? $('Merge Pair Error').first().json.mergeError : '';
const results = $input.first().json.results || [];
const history = r => String((r.properties || {}).hs_merged_object_ids || '').split(';').map(x => x.trim()).filter(Boolean);
const resolve = id => results.find(r => String(r.id) === id) || results.find(r => history(r).includes(id)) || null;
const keep = resolve(String(p.p)), other = resolve(String(p.s));
let outcome = 'merge';
if (!keep || !other) outcome = 'deleted';
else if (String(keep.id) === String(other.id)) outcome = mergeError ? 'merged_after_error' : 'already_merged';
else if (mergeError) outcome = 'failed';
return [{ json: { outcome, mergeError, primaryNow: keep ? String(keep.id) : null, secondaryNow: other ? String(other.id) : null, request: keep && other ? { primaryObjectId: String(keep.id), objectIdToMerge: String(other.id) } : null } }];

// Saves the decision (the link can never be used again) and builds the page and the Slack note.
const html = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const slack = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const page = (title, inner) => '<!doctype html><html lang="en"><head><meta charset="utf-8">'
  + '<meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex">'
  + `<title>${html(title)}</title><style>`
  + 'body{font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;max-width:560px;margin:40px auto;padding:0 16px;color:#1f2933;background:#fff;line-height:1.5}'
  + 'h1{font-size:22px}.card{border:1px solid #d9e2ec;border-radius:8px;padding:12px 16px;margin:8px 0 16px}.muted{color:#52606d;font-size:14px}'
  + 'button{font-size:16px;padding:10px 18px;border-radius:6px;border:0;background:#1f6feb;color:#fff;cursor:pointer}button.skip{background:#52606d}'
  + `</style></head><body><h1>${html(title)}</h1>${inner}</body></html>`;
const tz = (() => { const z = String($env.REPORT_TIMEZONE || '').trim() || 'UTC'; try { new Intl.DateTimeFormat('en-US', { timeZone: z }); return z; } catch (e) { return 'UTC'; } })();
const plainSpaces = t => t.replace(/[\u202f\u00a0]/g, ' ');
const when = value => {
  const d = typeof value === 'number' ? new Date(value * 1000) : new Date(value);
  if (isNaN(d)) return '';
  return plainSpaces(new Intl.DateTimeFormat('en-US', { timeZone: tz, month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' }).format(d)) + ` (${tz})`;
};
const c = $('Check Approval').first().json;
// The last read of the pair: before the merge, or after a merge call that failed.
const pair = $('Check Pair').first().json;
const st = $getWorkflowStaticData('global');
const entry = st.approvals[c.payload.k];
let outcome = pair.outcome, newId = '';
if (outcome === 'merge') { outcome = 'merged'; newId = String($input.first().json.id); }     // HubSpot answered the merge
else if (outcome === 'merged_after_error') { outcome = 'merged'; newId = String(pair.primaryNow); }
entry.status = outcome;
entry.decidedAt = new Date().toISOString();
const a = entry.primary, b = entry.secondary;
let title, body, note;
if (outcome === 'merged') {
  entry.newId = newId;
  title = 'Merged';
  if (pair.outcome === 'merge') {
    body = `<p>${html(b.name)} (record ${html(pair.secondaryNow)}) was merged into ${html(a.name)} (record ${html(pair.primaryNow)}). The merged record's ID is ${html(newId)}.</p>`;
    note = `*Duplicate approved and merged*: ${slack(a.name)}. Kept record ${pair.primaryNow}, merged in ${pair.secondaryNow}, new record ID ${newId}.`;
  } else {
    body = `<p>HubSpot answered the merge with an error, but reading the records again shows ${html(b.name)} (record ${html(entry.secondaryId)}) and ${html(a.name)} (record ${html(entry.primaryId)}) are now one record, so the merge went through. The merged record's ID is ${html(newId)}.</p>`;
    note = `*Duplicate approved and merged*: ${slack(a.name)}. Kept record ${entry.primaryId}, merged in ${entry.secondaryId}, new record ID ${newId}. HubSpot answered with an error, but reading the records again shows one record.`;
  }
} else if (outcome === 'already_merged') {
  title = 'Already merged';
  body = `<p>Someone already merged these records in HubSpot (both now point to record ${html(pair.primaryNow)}), so there was nothing to do.</p>`;
  note = `*Duplicate approved, already merged*: ${slack(a.name)} (records ${entry.primaryId} and ${entry.secondaryId}) were merged in HubSpot before the link was used. Nothing else was done.`;
} else {
  title = 'Record not found';
  body = '<p>One of the records is no longer in HubSpot (deleted, or merged away), so nothing was merged.</p>';
  note = `*Duplicate approved, but a record is gone*: ${slack(a.name)} (record ${entry.primaryId}) or ${slack(b.name)} (record ${entry.secondaryId}) is no longer in HubSpot. Nothing was merged.`;
}
// A decided pair keeps only record IDs in n8n's memory: names and emails are not needed any more.
entry.primary = { id: entry.primaryId };
entry.secondary = { id: entry.secondaryId };
return [{ json: { httpStatus: 200, html: page(title, body), note, outcome } }];

// HubSpot did not answer or refused, after the retries, and (after a merge call) reading the records again still shows
// two records or did not work. The pair keeps waiting, so the same link works again later.
const html = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const slack = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const page = (title, inner) => '<!doctype html><html lang="en"><head><meta charset="utf-8">'
  + '<meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex">'
  + `<title>${html(title)}</title><style>`
  + 'body{font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;max-width:560px;margin:40px auto;padding:0 16px;color:#1f2933;background:#fff;line-height:1.5}'
  + 'h1{font-size:22px}.card{border:1px solid #d9e2ec;border-radius:8px;padding:12px 16px;margin:8px 0 16px}.muted{color:#52606d;font-size:14px}'
  + 'button{font-size:16px;padding:10px 18px;border-radius:6px;border:0;background:#1f6feb;color:#fff;cursor:pointer}button.skip{background:#52606d}'
  + `</style></head><body><h1>${html(title)}</h1>${inner}</body></html>`;
const tz = (() => { const z = String($env.REPORT_TIMEZONE || '').trim() || 'UTC'; try { new Intl.DateTimeFormat('en-US', { timeZone: z }); return z; } catch (e) { return 'UTC'; } })();
const plainSpaces = t => t.replace(/[\u202f\u00a0]/g, ' ');
const when = value => {
  const d = typeof value === 'number' ? new Date(value * 1000) : new Date(value);
  if (isNaN(d)) return '';
  return plainSpaces(new Intl.DateTimeFormat('en-US', { timeZone: tz, month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' }).format(d)) + ` (${tz})`;
};
const c = $('Check Approval').first().json;
const mergeError = $('Merge Pair Error').isExecuted ? $('Merge Pair Error').first().json.mergeError : '';
const e = $input.first().json.error;
const readError = e ? (e.message || e.description || 'unknown error') : '';
const step = mergeError ? 'merge' : 'check';
const what = mergeError && readError ? `the merge call failed (${mergeError}) and the records could not be read again (${readError})`
  : mergeError ? `the merge call failed (${mergeError}) and reading the records again shows they are still two`
  : `the records could not be read from HubSpot (${readError || 'unknown error'})`;
const entry = c.entry;
const names = `${entry.primary.name} (record ${entry.primaryId}) and ${entry.secondary.name} (record ${entry.secondaryId})`;
return [{ json: {
  httpStatus: 502,
  html: page('HubSpot did not confirm the merge', `<p>${step === 'merge' ? 'HubSpot did not confirm the merge' : 'The records could not be read from HubSpot'}, so this approval is not finished. `
    + 'Open the records in HubSpot to check. If they are still two records, this link still works: try it again in a few minutes.</p>'),
  stopMessage: slack(`An approved merge of ${names} did not go through: ${what}. The pair still waits for approval, so the same link can be used again. Check the records in HubSpot first.`),
} }];

// HubSpot refused the approved merge or did not answer, after 3 tries. Its answer may have been lost after it saved the
// merge (a retry is then refused, because both IDs already belong to one record), or a second click merged them first.
// So both records are read again before anything is reported.
const e = $input.first().json.error || {};
return [{ json: { payload: $('Check Approval').first().json.payload, mergeError: e.message || e.description || 'unknown error' } }];

// The contacts of a batch HubSpot refused as a whole go out again one at a time, so the valid ones are saved and the
// refused ones are named. At most 100 per run, spaced out (HubSpot allows 100 requests per 10 seconds); the rest keep
// the batch's error and wait for the next run.
const inputs = $input.all().flatMap(i => i.json.retryAlone || []);
if (!inputs.length) return [{ json: { none: true } }];
return inputs.slice(0, 100).map(input => ({ json: { id: String(input.id), request: { inputs: [input] } } }));

// HubSpot's answer for each contact sent alone: saved, or refused with HubSpot's reason.
const sent = $('Plan One by One').all().map(i => i.json);
const answers = new Map();
$input.all().forEach((it, i) => {
  const p = it.pairedItem;
  answers.set(p && !Array.isArray(p) && Number.isInteger(p.item) ? p.item : i, it.json || {});
});
const okIds = [], failed = [];
sent.forEach((s, i) => {
  const a = answers.get(i) || {};
  const status = Number(a.statusCode) || 0;
  let body = a.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* keep the text */ } }
  if (status === 200) { okIds.push(s.id); return; }
  const why = status === 0 ? `no answer from HubSpot (${(a.error && (a.error.message || a.error.description)) || 'connection failed'})`
    : `${status} ${body && typeof body === 'object' ? (body.message || body.category || '') : String(body || '').slice(0, 200)}`.trim();
  failed.push({ id: s.id, message: `${why} (sent alone after HubSpot refused its batch)` });
});
return [{ json: { sent: sent.map(s => s.id), okIds, failed } }];
